begin;
create role authenticated nologin;
create role anon nologin;
create role service_role nologin bypassrls;
create schema private;
create schema auth;
create function auth.uid() returns uuid language sql as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,public to authenticated,service_role;
create table public.professional_profiles(id uuid primary key);
create table public.patients(id uuid primary key,professional_id uuid,deleted_at timestamptz);
create table public.consultations(id uuid primary key,professional_id uuid,patient_id uuid,deleted_at timestamptz);
grant select on public.professional_profiles,public.patients,public.consultations to service_role;
-- MIGRATION --
insert into public.professional_profiles values ('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
insert into public.patients values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',null),('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000002',null);
insert into public.consultations values('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',null);
update private.ai_feature_config set enabled=true,model='synthetic-test',pricing_version='test-only',max_input_tokens=8000,max_output_tokens=2000,input_usd_per_million=1,cached_usd_per_million=0.5,output_usd_per_million=2 where feature='core_check';
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',label;end if;end$$;
create function pg_temp.reject(query text,expected text) returns void language plpgsql as $$begin execute query; raise exception 'Operation unexpectedly succeeded'; exception when others then if sqlerrm<>expected and sqlstate<>expected then raise; end if; end$$;
create function pg_temp.reserve(owner_id uuid,key_id uuid,patient_id uuid default null,consultation_id uuid default null) returns jsonb language sql as $$
select public.ai_server('reserve',owner_id,jsonb_build_object('feature','core_check','idempotency_key',key_id,'request_hash',repeat('a',64),'patient_id',patient_id,'consultation_id',consultation_id,'config',public.ai_server('config',owner_id,'{"feature":"core_check"}')))
$$;
set local role service_role;
select public.ai_grant_credits('00000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','PLAN_ALLOCATION',1,now()-interval '1 day',now()+interval '29 days');
select public.ai_grant_credits('00000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','PURCHASE',10);
select public.ai_grant_credits('00000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','PURCHASE',10);
select public.ai_grant_credits('00000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000003','PURCHASE',0.1);
select pg_temp.reject($q$select pg_temp.reserve('00000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001')$q$,'insufficient_credits');
select pg_temp.reject($q$select pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002')$q$,'context_unavailable');
select pg_temp.reject($q$select pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',null,'20000000-0000-0000-0000-000000000001')$q$,'context_unavailable');
select pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001');
select pg_temp.assert_true((pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001')->>'created')::boolean=false,'idempotent reservation');
select pg_temp.assert_true((select reserved_included=1 and reserved_purchased=0.2 and purchased_credits=10 from private.ai_accounts where professional_id='00000000-0000-0000-0000-000000000001'),'included first; allocation idempotent');
select public.ai_server('claim','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id)) from private.ai_generations;
select pg_temp.assert_true((public.ai_server('claim','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id))->>'claimed')::boolean=false,'one dispatch') from private.ai_generations;
select public.ai_server('settle','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id,'status','succeeded','input_tokens',1000,'output_tokens',100,'cached_tokens',500)) from private.ai_generations;
select public.ai_server('settle','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id,'status','succeeded','input_tokens',1000,'output_tokens',100,'cached_tokens',500)) from private.ai_generations;
select pg_temp.assert_true((select included_credits=0.905 and purchased_credits=10 and reserved_included=0 and reserved_purchased=0 from private.ai_accounts where professional_id='00000000-0000-0000-0000-000000000001'),'exact settlement cached rate and release');
select pg_temp.assert_true((select count(*)=1 from private.ai_credit_ledger where type='USAGE'),'one usage charge');
select pg_temp.assert_true((select total_tokens=1100 and charged_credits=0.095 and actual_cost=0.00095 from private.ai_generations),'usage audit');
select pg_temp.assert_true((select purchased_credits=0.1 and reserved_purchased=0 from private.ai_accounts where professional_id='00000000-0000-0000-0000-000000000002'),'other tenant untouched');
select pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002');
select public.ai_server('settle','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id,'status','failed','input_tokens',0,'output_tokens',0,'cached_tokens',0)) from private.ai_generations where status='reserved';
select pg_temp.assert_true((select included_credits=0.905 and reserved_included=0 from private.ai_accounts where professional_id='00000000-0000-0000-0000-000000000001'),'pre-consumption error refunds reservation');
select pg_temp.reserve('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003');
select public.ai_server('claim','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id)) from private.ai_generations where status='reserved';
select public.ai_server('uncertain','00000000-0000-0000-0000-000000000001',jsonb_build_object('generation_id',id)) from private.ai_generations where status='running';
select pg_temp.assert_true((select reserved_included+reserved_purchased=1.2 from private.ai_accounts where professional_id='00000000-0000-0000-0000-000000000001'),'uncertain retains reserve');
select pg_temp.reject($q$delete from private.ai_credit_ledger$q$,'42501');
select pg_temp.reject($q$update private.ai_credit_ledger set included_delta=100$q$,'42501');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((public.ai_balance()->>'available_credits')::numeric=0.1,'owner-only balance');
select pg_temp.reject($q$select * from private.ai_accounts$q$,'42501');
select pg_temp.reject($q$select public.ai_server('reserve','00000000-0000-0000-0000-000000000001','{}')$q$,'42501');
select pg_temp.reject($q$select public.ai_grant_credits('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'PURCHASE',100)$q$,'42501');
reset role;
set local role anon;
select pg_temp.reject($q$select public.ai_balance()$q$,'42501');
reset role;
select pg_temp.assert_true((select bool_and(relrowsecurity) from pg_class where oid in ('private.ai_accounts'::regclass,'private.ai_credit_ledger'::regclass,'private.ai_generations'::regclass,'private.ai_feature_config'::regclass)),'RLS enabled');
rollback;
